-- Week 12 PostgreSQL disclosure queries.
SET client_encoding = 'UTF8';
SET search_path TO pevc_week12;
\copy (SELECT table_name, row_count FROM (SELECT 'week12_source_catalog' AS table_name, count(*)::text AS row_count FROM "week12_source_catalog" UNION ALL SELECT 'week12_source_inventory' AS table_name, count(*)::text AS row_count FROM "week12_source_inventory" UNION ALL SELECT 'week12_expanded_company_universe' AS table_name, count(*)::text AS row_count FROM "week12_expanded_company_universe" UNION ALL SELECT 'week12_processing_queue' AS table_name, count(*)::text AS row_count FROM "week12_processing_queue" UNION ALL SELECT 'week12_source_summary' AS table_name, count(*)::text AS row_count FROM "week12_source_summary" UNION ALL SELECT 'week12_board_coverage_summary' AS table_name, count(*)::text AS row_count FROM "week12_board_coverage_summary" UNION ALL SELECT 'week12_field_source_matrix' AS table_name, count(*)::text AS row_count FROM "week12_field_source_matrix" UNION ALL SELECT 'week12_weekly_plan' AS table_name, count(*)::text AS row_count FROM "week12_weekly_plan" UNION ALL SELECT 'week12_scaling_protocol' AS table_name, count(*)::text AS row_count FROM "week12_scaling_protocol" UNION ALL SELECT 'week12_quality_gates' AS table_name, count(*)::text AS row_count FROM "week12_quality_gates" UNION ALL SELECT 'week12_database_load_plan' AS table_name, count(*)::text AS row_count FROM "week12_database_load_plan" UNION ALL SELECT 'week12_submission_checklist' AS table_name, count(*)::text AS row_count FROM "week12_submission_checklist") q ORDER BY table_name) TO 'database/postgresql_week12_table_counts.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8');
\copy (SELECT '数据库类型' AS item, 'PostgreSQL临时实例/扩样计划表' AS value, '用于验证第十二周来源台账和扩样队列可入库' AS source_note UNION ALL SELECT '临时库导入表数量', count(*)::text, 'pevc_week12 schema中的Week12派生表' FROM information_schema.tables WHERE table_schema='pevc_week12' UNION ALL SELECT '临时库导入总行数' AS item, sum(row_count)::text AS value, 'Week12派生表合计行数' AS source_note FROM (SELECT count(*) AS row_count FROM "week12_source_catalog" UNION ALL SELECT count(*) AS row_count FROM "week12_source_inventory" UNION ALL SELECT count(*) AS row_count FROM "week12_expanded_company_universe" UNION ALL SELECT count(*) AS row_count FROM "week12_processing_queue" UNION ALL SELECT count(*) AS row_count FROM "week12_source_summary" UNION ALL SELECT count(*) AS row_count FROM "week12_board_coverage_summary" UNION ALL SELECT count(*) AS row_count FROM "week12_field_source_matrix" UNION ALL SELECT count(*) AS row_count FROM "week12_weekly_plan" UNION ALL SELECT count(*) AS row_count FROM "week12_scaling_protocol" UNION ALL SELECT count(*) AS row_count FROM "week12_quality_gates" UNION ALL SELECT count(*) AS row_count FROM "week12_database_load_plan" UNION ALL SELECT count(*) AS row_count FROM "week12_submission_checklist") s UNION ALL SELECT '扩样公司universe数量', count(*)::text, 'week12_expanded_company_universe' FROM week12_expanded_company_universe UNION ALL SELECT '本周优先处理队列数量', count(*)::text, 'week12_processing_queue' FROM week12_processing_queue UNION ALL SELECT '含URL来源公司数量', count(*)::text, 'prospectus_url或source_page_url非空' FROM week12_expanded_company_universe WHERE coalesce(prospectus_url,'') <> '' OR coalesce(source_page_url,'') <> '' UNION ALL SELECT '含本地PDF公司数量', count(*)::text, 'local_pdf_path非空' FROM week12_expanded_company_universe WHERE coalesce(local_pdf_path,'') <> '' UNION ALL SELECT '含页码化文本公司数量', count(*)::text, 'local_text_path非空' FROM week12_expanded_company_universe WHERE coalesce(local_text_path,'') <> '') TO 'database/postgresql_week12_disclosure.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8');
